    edu_fundamentosComprarVsVende_6227e3cc: 'الأساسيات: شراء مقابل بيع الخيارات',
    edu_todaOperacionConOpciones_4b806806: 'كل عملية خيارات لها طرفان. من يشتري (Long) يدفع البريميوم ويحصل على حق. من يبيع (Short) يحصل على البريميوم ويقبل الالتزام إذا تم التنفيذ.',
    edu_lasGriegas_0ebfaf86: 'الإغريقيات',
    edu_lasGriegasCuantificanLa_560a7bae: 'الإغريقيات تحدد حساسية البريميوم أمام عوامل مختلفة. إتقانها هو ما يفصل المتداول المحترف عن الهاوي.',
    edu_moneynessItmAtmOtm_a4a14296: 'Moneyness: ITM / ATM / OTM (شرح)',
    edu_laMoneynessIndicaLa_d33c00c2: 'الـ MONEYNESS تشير إلى العلاقة بين السعر الحالي للأصل الأساسي (Spot S) والـ Strike K. تحدد القيمة الجوهرية للخيار وسلوكه.',
    edu_volatilidadImplicitaIv_9566fdd4: 'التقلب الضمني (IV)',
    edu_laIvEsEl_8e2ceb1e: 'الـ IV هو سعر السوق لعدم اليقين المستقبلي. IV مرتفع يجعل البريميوم أكثر تكلفة؛ IV منخفض يجعلها أرخص. هو العامل الأكثر أهمية بعد Delta.',
    edu_comoLeerElDiagrama_0e91a1f2: 'كيفية قراءة مخطط الـ Payoff',
    edu_elGraficoDePayoff_4228af6d: 'رسم الـ Payoff يظهر الـ PnL (المحور Y) بناءً على سعر الأصل الأساسي عند انتهاء الصلاحية (المحور X). الخطان الرئيسيان هما T+0 (اليوم) و At Expiry (انتهاء الصلاحية).',
    edu_longCallBuyCall_b69bddbc: 'LONG CALL (BUY CALL) → تدفع بريميوم. تربح إذا ارتفع > Strike+البريميوم. الخسارة القصوى = البريميوم المدفوع.',
    edu_longPutBuyPut_0125f4de: 'LONG PUT (BUY PUT) → تدفع بريميوم. تربح إذا انخفض < Strike−البريميوم. الخسارة القصوى = البريميوم المدفوع.',
    edu_shortCallSellCall_46b9297a: 'SHORT CALL (SELL CALL) → تحصل على بريميوم. تخسر إذا ارتفع > Strike+البريميوم. الخسارة القصوى = غير محدودة (إذا كان naked).',
    edu_shortPutSellPut_cc28336a: 'SHORT PUT (SELL PUT) → تحصل على بريميوم. تخسر إذا انخفض < Strike−البريميوم. الخسارة القصوى = Strike−البريميوم إذا انخفض إلى 0.',
    edu_regla802080_db62e282: 'قاعدة 80/20 → ~80% من الخيارات تنتهي بدون قيمة → إحصائياً بائع البريميوم عادة يربح؛ لكن نسبة المخاطرة/المكافأة سيئة.',
    edu_deltaCambioEnPrima_0791393e: 'Delta Δ → التغير في البريميوم مقابل تحرك $1 للأصل الأساسي. Calls: من 0 إلى +1. Puts: من 0 إلى -1.',
    edu_thetaPerdidaDeValor_c24fe104: 'Theta Θ → خسارة القيمة الزمنية لكل يوم يمر. دائماً سلبية لـ Long، إيجابية لـ Short.',
    edu_vegaSensibilidadAlCambio_49f4d565: 'Vega ν → الحساسية للتغير في التقلب الضمني (IV). إيجابية لـ Long، سلبية لـ Short.',
    edu_gammaVelocidadDeCambio_2647e1e9: 'Gamma Γ → سرعة تغير الـ Delta؛ الحد الأقصى بالقرب من ATM. Long: Gamma إيجابي. Short: Gamma سلبي.',
    edu_rhoSensibilidadACambios_6dd807ab: 'Rho ρ → الحساسية للتغيرات في أسعار الفائدة. مهمة فقط للخيارات طويلة الأجل (LEAPS).',
    edu_call_094692fa: '── CALL ──',
    edu_itmInTheMoney_d20317a8: 'ITM (In-The-Money) → S > K. له قيمة جوهرية = S−K. Delta > 0.5. سلوك "مثل السهم".',
    edu_atmAtTheMoney_638c9e7d: 'ATM (At-The-Money) → S ≈ K. بدون قيمة جوهرية؛ فقط قيمة زمنية. Delta ≈ 0.5. أقصى Gamma و Vega.',
    edu_otmOutOfThe_2b67777e: 'OTM (Out-of-The-Money) → S < K. بدون قيمة جوهرية؛ فقط قيمة زمنية. Delta < 0.5. أرخص لكن أكثر خطورة.',
    edu_put_a27fa8fc: '── PUT ──',
    edu_itmInTheMoney_bfd445a5: 'ITM (In-The-Money) ← S < K. له قيمة جوهرية = K−S. Delta < −0.5.',
    edu_atmAtTheMoney_793be97c: 'ATM (At-The-Money) ← S ≈ K. بدون قيمة جوهرية؛ قيمة زمنية فقط. Delta ≈ −0.5.',
    edu_otmOutOfThe_71ddb79d: 'OTM (Out-of-The-Money) ← S > K. بدون قيمة جوهرية؛ قيمة زمنية فقط. Delta > −0.5.',
    edu_cLculoDelPayoff_2fb38b8e: '── حساب Payoff عند الاستحقاق ──',
    edu_longCallPnlMax_e997a851: 'Long Call:  PnL = max(0, S−K) × 100 × عقود − Prima مدفوعة × 100',
    edu_longPutPnlMax_80f585a4: 'Long Put:   PnL = max(0, K−S) × 100 × عقود − Prima مدفوعة × 100',
    edu_shortCallPnlPrima_d573157a: 'Short Call: PnL = Prima محصلة × 100 − max(0, S−K) × 100 × عقود',
    edu_shortPutPnlPrima_47fd35c2: 'Short Put:  PnL = Prima محصلة × 100 − max(0, K−S) × 100 × عقود',
    edu_ivRankIvPercentile_da54acc4: 'IV Rank / IV Percentile ← يضعان IV الحالية في سياق تاريخي (آخر 52 أسبوع).',
    edu_crushPostEarningsLa_c269719f: 'Crush بعد الأرباح ← تنهار IV بعد الحدث؛ المشترون عادة يخسرون حتى لو توقعوا الاتجاه صحيحاً.',
    edu_vegaLongVsShort_404de31c: 'Vega Long مقابل Short ← المشترون يربحون إذا ارتفعت IV؛ البائعون إذا انخفضت.',
    edu_reglaPracticaComprarOpcio_98a9dbf8: 'قاعدة عملية: BUY خيارات مع IV منخفضة (IV Rank < 30)، SELL مع IV مرتفعة (IV Rank > 50).',
    edu_skewLasPutsOtm_02473640: 'Skew ← عادة PUT OTM لها IV أعلى من CALL OTM (خوف من الانخفاضات).',
    edu_lineaVerdeCurrentP_ecfc0457: 'الخط الأخضر (Current P&L) ← PnL النظري اليوم عند أسعار مختلفة باستخدام Black-Scholes (يتضمن القيمة الزمنية).',
    edu_lineaBlancaPunteadaAt_8a5c4ef9: 'الخط الأبيض المنقط (At Expiry) ← PnL إذا احتفظت حتى الاستحقاق (بدون قيمة زمنية).',
    edu_lineaNaranjaSpotPrecio_de21f24f: 'الخط البرتقالي (Spot) ← السعر الحالي للأصل الأساسي. المرجع الرئيسي.',
    edu_lineaVioletaBreakEven_9112e631: 'الخط البنفسجي (Break-Even) ← النقطة حيث PnL = 0 عند الاستحقاق. فوق/تحت تربح.',
    edu_zonaVerdeRangoDe_49e82b2d: 'المنطقة الخضراء ← نطاق الأسعار حيث تنتهي بربح. المنطقة الحمراء ← خسائر.',
    edu_zonasDeMoneynessNuevas_d71f9261: 'مناطق MONEYNESS (جديدة) ← أخضر فاتح = ITM، أصفر = ATM، أحمر فاتح = OTM. يساعد على تصور موقع كل Strike.',
    edu_laDiferenciaEntreAmbas_439232b3: 'الفرق بين الخطين = القيمة الخارجية (الوقت + IV). Theta السالب يقللها كل يوم.',
