    mechTitle: 'ميكانيكا السوق',
    mechIntro: 'فهم كيفية عمل الأسواق وأنواع الأوامر واختيار الوسيط',
    ordersTitle: 'أنواع الأوامر',
    orderMarketName: 'أمر السوق',
    orderMarketDesc: 'اشترِ أو بِع الآن بأفضل سعر متاح في تلك اللحظة. الميزة: دخولك مضمون. العيب: في الأسواق السريعة أو قليلة السيولة تدفع فرق السعر وقد تتعرض لانزلاق (تُنفَّذ عند 100.05 بدل 100.00). استخدمها حين يكون الدخول أو الخروج أهم من السنت الدقيق.',
    orderMarketUse: 'عندما تهم السرعة أكثر من السعر',
    orderLimitName: 'أمر محدد',
    orderLimitDesc: 'حدّد أعلى سعر تشتري به (أو أدنى سعر تبيع به): لا تُنفَّذ إلا عند ذلك السعر أو أفضل منه. الميزة: تتحكم بالسعر ولا تدفع زيادة. العيب: إن لم يصل السوق إلى سعرك تفوتك الصفقة. مثالية للدخول بصبر عند الدعم والمقاومة.',
    orderLimitUse: 'عندما يهم السعر أكثر من السرعة',
    orderStopName: 'أمر الإيقاف',
    orderStopDesc: 'أمر معلّق يتحوّل إلى أمر سوقي عندما يبلغ السعر مستواك. استخدامان: كوقف خسارة (يُخرجك إن سار السعر عكسك) أو للدخول عند الاختراق. انتبه: بعد تفعيله يُنفَّذ بسعر السوق، فقد يُنفَّذ في فجوة سعرية أسوأ من مستواك.',
    orderStopUse: 'حماية وقف الخسارة، مداخل الاختراق',
    orderStopLimitName: 'إيقاف محدد',
    orderStopLimitDesc: 'مثل أمر الإيقاف، لكنه عند التفعيل يضع أمرًا محدّدًا (ليميت) بدل أمر سوقي. تتحكم بسعر التنفيذ، لكن المقابل هو احتمال عدم تنفيذه إطلاقًا إذا تجاوز السعر بسرعة. مفيد لتفادي الانزلاق؛ وخطير كوقف خسارة لأنه قد يتركك دون إغلاق.',
    orderStopLimitUse: 'تنفيذ مضبوط عند الاختراق',
    orderTrailingName: 'وقف خسارة متحرك',
    orderTrailingDesc: 'وقف خسارة ديناميكي يتبع السعر بمسافة ثابتة (يصعد في الشراء ويهبط في البيع) لكنه لا يتراجع أبدًا. يؤمّن الربح تلقائيًا بينما تترك الصفقة الرابحة تجري، ويُخرجك حين ينعكس السعر بمقدار تلك المسافة. مفتاح \'اقطع الخسارة واترك الربح يجري\' دون مراقبة.',
    orderTrailingUse: 'تأمين الأرباح مع ترك الصفقات الرابحة تجري',
    brokerTitle: 'اختيار الوسيط',
    brokerIntro: 'وسيطك هو بوابتك للأسواق — اختر بحكمة',
    brokerRegulationName: 'التنظيم',
    brokerRegulationDesc: 'تداول فقط مع وسطاء تنظّمهم جهات جادّة (FCA في بريطانيا، CFTC/NFA في أمريكا، ASIC في أستراليا، CySEC في أوروبا). التنظيم يُلزمهم بفصل أموالك عن أموالهم (حسابات منفصلة) ويمنحك جهة تشتكي إليها. وبدون تنظيم متين، وديعتك غير محمية.',
    brokerSpreadName: 'الفروقات',
    brokerSpreadDesc: 'الفرق بين سعر الشراء وسعر البيع: تكلفتك المباشرة في كل صفقة، إضافةً إلى أي عمولة. فرق نقطة واحدة على EUR/USD طبيعي، و3 نقاط أو أكثر مرتفع. في المضاربة السريعة يلتهم الفرق جزءًا كبيرًا من ربحك، فقارنه بين الوسطاء قبل الاختيار.',
    brokerLeverageName: 'الرافعة المالية',
    brokerLeverageDesc: 'تضاعف المكاسب والخسائر — استخدم بحذر شديد',
    brokerExecutionName: 'التنفيذ',
    brokerExecutionDesc: 'سرعة وموثوقية تنفيذ أوامرك. مهمة جدًا في التداول السريع وحول الأخبار: إعادة التسعير أو التأخير أو الرفض تكلّفك مالاً حقيقيًا. ابحث عن تنفيذ من نوع ECN/STP (أمرك يذهب إلى السوق) واحذر الوسطاء الذين يأخذون الجهة المقابلة ضدّك إن كنت تتداول كثيرًا.',
