    platformTVBest: 'الأفضل لـ: التحليل والبحث',
    platformMT4Name: 'MetaTrader 4',
    platformMT4Desc: 'المعيار الصناعي للفوركس، التداول الآلي',
    platformMT4Best: 'الأفضل لـ: الفوركس وعقود الفروقات',
    platformMT5Name: 'MetaTrader 5',
    platformMT5Desc: 'منصة متعددة الأصول مع أنواع أوامر متقدمة',
    platformMT5Best: 'الأفضل لـ: التداول متعدد الأصول',
    journalTitle: 'مجلة التداول',
    journalWhyName: 'لماذا المجلة؟',
    journalWhyDesc: 'يحتفظ كبار المتداولين بمذكّرات لأنها أسرع طريقة لرؤية أنماطك: أي النماذج تربّحك، وفي أي وقت تخسر، وكيف تخرّبك المشاعر. بدون سجلّ، تكرّر الأخطاء نفسها دون أن تنتبه. إنه الفرق بين \'التداول\' و\'التحسّن\' الحقيقي.',
    journalTrackName: 'ما تتبعه',
    journalTrackDesc: 'دوّن لكل صفقة: الدخول، الخروج، الحجم، نوع النموذج، المخاطرة بوحدة R، النتيجة، ظروف السوق، وحالتك الشعورية (خوف، نشوة، ملل). أضِف لقطة للرسم البياني. بعد 30-50 صفقة تظهر أنماط واضحة ما كنت لتراها من الذاكرة.',
    journalReviewName: 'عملية المراجعة',
    journalReviewDesc: 'راجع المذكّرة كل أسبوع وكل شهر بحثًا عمّا تكرّره: أفضل نماذجك (أكثِر منها)، ومواطن تسرّب أموالك (اقطعها)، وأنماط السوق. المراجعة، لا الصفقة نفسها، هي حيث يحدث التعلّم الحقيقي. كن صادقًا — المذكّرة لك لا للتباهي.',

