    basicsFaqShort1A: 'أن تكون في مركز Short يعني أنك تبيع أصلاً لا تمتلكه (تقترضه من الوسيط) متوقعاً انخفاض سعره. عندما ينخفض السعر، تعيد الشراء بسعر أرخص وتحتفظ بالفرق كربح.',
    basicsFaqShort2Q: 'متى تفتح مركز Short؟',
