    basicsFaqShort3Q: 'هل Short أكثر خطورة من Long؟',
    basicsFaqShort3A: 'نظرياً نعم. في Long الخسارة القصوى 100% (يصل السعر إلى الصفر). في Short الخسارة نظرياً غير محدودة (يمكن للسعر الارتفاع بلا سقف). لهذا السبب يُعدّ SL المُوضَع بشكل صحيح أكثر أهمية في صفقات Short.',
    basicsTpTitle: 'Take Profit (TP) — هدف الربح',
