    basicsTpDesc: 'Take Profit هو أمر يغلق مركزك تلقائياً عندما يصل السعر إلى هدف الربح المحدد مسبقاً. إنه الأداة التي تحارب الطمع: تجبرك على جني الأرباح عند النقطة التي يشير إليها التحليل.',
    basicsTpBen1Title: 'يُزيل الطمع',
    basicsTpBen1Desc: 'يغلق تلقائياً دون أن تجعلك العواطف تنتظر أكثر مما يشير إليه التحليل.',
    basicsTpBen2Title: 'تداول دون حضور',
    basicsTpBen2Desc: 'تُدار السوق من تلقاء ذاتها. يمكنك النوم والنظام يغلق المركز عند هدفك.',
    basicsTpBen3Title: 'يُثبّت نسبة R/R',
    basicsTpBen3Desc: 'بتحديد TP وSL قبل الدخول، تُحسب نسبة المخاطرة/العائد مسبقاً.',
    basicsTpBen4Title: 'انضباط النظام',
    basicsTpBen4Desc: 'اتباع خطة التداول يتطلب الإغلاق عند الأهداف المحددة مسبقاً، لا "عندما يبدو الأمر مناسباً".',
